import type { RoomStage } from './shells.generated';

/**
 * 칸마다 실제 바닥인지 표시한 표. '.'는 바닥, 'X'는 허공이다.
 *
 * 격자는 사각형인데 방은 아니다(별관이 붙은 L자, 나무 테두리에 걸친
 * 가장자리 칸). scripts/measure-floor-masks.py가 셸 픽셀에서 잰다.
 * 손으로 고치지 말 것.
 */
export const FLOOR_MASKS: Record<RoomStage, readonly string[]> = {
  stage0: [
    'XX.......',
    'X........',
    'X........',
    'X........',
    'X........',
    'X........',
    'X........',
    'X........',
    'X........',
  ],
  stage1: [
    'XX...........',
    'X............',
    'X............',
    'X............',
    'X............',
    'X............',
    '.............',
    'X............',
    'X............',
    'X............',
    'X............',
  ],
  stage2: [
    'XX...........XXXXX',
    'X.................',
    'X.................',
    'X.................',
    'X.................',
    'X.................',
    'X.................',
    'X.................',
    'X.................',
    'X.................',
    'X.................',
    'X.................',
    'XXXXXX............',
  ],
  stage3: [
    'XXXX...XXXXXXXXXXXXXXXXXXXX',
    'XX.........................',
    'X..........................',
    'X..........................',
    'X..........................',
    'X..........................',
    '...........................',
    '...........................',
    '...........................',
    '...........................',
    '...........................',
    '...........................',
    'XXX........................',
    'XXXXXXXXX..................',
  ],
  stage4: [
    'XXXXXXXXXXXXXXXXXXXXXXXXXXXX.XXXXXXXXXXX',
    'XXXXXXXXXXXXXXXXXXXXXXXXXXXX...XXXXXXXXX',
    'XXXXX............XXXXXXXXXXX.....XXX....',
    'XXXX..................XXXXXX............',
    'XXXX....................................',
    'XXXX................................XXXX',
    'XXX.................................XXXX',
    'XXX.................................XXXX',
    'XXX.................................XXXX',
    'XX..................................XXXX',
    'XXX.................................XXXX',
    'XX..................................XXXX',
    'XX..................................XXXX',
    'XX..................................XXXX',
    'XX...................................XXX',
    'XX...................................XXX',
    'X....................................XXX',
    'XXX..................................XXX',
    'XXXXXXXXX............................XXX',
    'XXXXXXXXXXXX.........................XXX',
  ],
};

export function isFloorCell(stage: RoomStage, x: number, y: number): boolean {
  const rows = FLOOR_MASKS[stage];
  const row = rows[Math.floor(y)];
  return row !== undefined && row[Math.floor(x)] === '.';
}
